import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.BetZR81g.js";const u=JSON.parse('{"title":"Development Guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/development.md"},"headers":[],"relativePath":"guide/development.md","filePath":"guide/development.md"}'),n={name:"guide/development.md"};function d(o,e,r,l,p,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="development-guide" tabindex="-1">Development Guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to &quot;Development Guide&quot;">​</a></h1><blockquote><p>This guide is for contributors changing source code, maintaining documentation or running repository tests. To use sfml.js as a dependency, start with <a href="/guide/getting-started">Quick start</a>.</p></blockquote><p><a href="/guide/">Documentation</a> · <a href="/guide/api">API guide</a> · <a href="/examples">Examples</a></p><p><a id="get-the-source"></a></p><h2 id="get-the-source" tabindex="-1">Get the source <a class="header-anchor" href="#get-the-source" aria-label="Permalink to &quot;Get the source&quot;">​</a></h2><p>Prepare Node.js, Python and a C++20 toolchain; see <a href="/guide/getting-started#requirements">requirements</a> for platform installation commands. Then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/XadillaX/node-sfml.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-sfml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span></code></pre></div><p><code>install</code> compiles the native module; <code>prepare</code> generates TypeScript constants, JavaScript and declaration files. Build hooks first check for and download SFML 3.1.0. When installed as an npm dependency, the package uses the published dist, so only the native module needs compiling during installation.</p><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><p>Run these commands from the repository root:</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>npm run build</code></td><td>Compile native code and TypeScript</td></tr><tr><td><code>npm run build:native</code></td><td>Compile native code and update clangd configuration</td></tr><tr><td><code>npm run build:ts</code></td><td>Generate constants and compile TypeScript</td></tr><tr><td><code>npm run build:docs</code></td><td>Build the four-language website and generated API reference</td></tr><tr><td><code>npm run build:reference</code></td><td>Generate TypeDoc API documentation only</td></tr><tr><td><code>npm run docs:dev</code></td><td>Preview the website during development</td></tr><tr><td><code>npm run docs:preview</code></td><td>Serve the production website build locally</td></tr><tr><td><code>npm run lint</code></td><td>Check source, tools, tests and examples</td></tr><tr><td><code>npm run test:types</code></td><td>Validate TypeScript APIs</td></tr><tr><td><code>npm run test:runtime</code></td><td>Run runtime tests serially; requires a prior build</td></tr><tr><td><code>npm test</code></td><td>Run lint, build, type checks and runtime tests in sequence</td></tr><tr><td><code>npm pack --dry-run</code></td><td>Inspect the npm package file list</td></tr></tbody></table><p>For TypeScript-only changes, run <code>npm run build:ts</code>; after native changes, run <code>npm run build</code>. Runtime tests do not rebuild automatically, so ensure the build matches the source before running them.</p><p><a id="testing"></a></p><h2 id="testing-and-verification" tabindex="-1">Testing and verification <a class="header-anchor" href="#testing-and-verification" aria-label="Permalink to &quot;Testing and verification&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p><code>npm test</code> runs lint, native and TypeScript builds, type checks and runtime tests.</p><p>Runtime tests run serially by file, covering public APIs, comparisons with native SFML, actual rendered pixels, asynchronous I/O, snapshots and lifetimes. Type tests are in <code>test/*.types.ts</code>, runtime tests in <code>test/*.test.cjs</code>, and native comparisons in <code>test/native/</code>.</p><p>Graphics tests require a display server and an OpenGL context. For headless Linux, install Xvfb as shown in <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/node.js.yml" target="_blank" rel="noreferrer">Linux CI</a>, then run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LIBGL_ALWAYS_SOFTWARE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  xvfb-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-screen 0 1280x1024x24 -noreset&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:runtime</span></span></code></pre></div><p>CI is configured for Node.js 20/22 on Linux, macOS and Windows; <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/node.js-windows.yml" target="_blank" rel="noreferrer">Windows CI</a> uses Mesa software OpenGL.</p><p>CI does not replace device testing for speakers, microphones, joysticks, sensors or fullscreen switching. SFML&#39;s macOS backend does not support Vulkan, and SuspendAwareClock.now supports only Android. State the actual platform and skipped cases when reporting results.</p><h2 id="maintaining-documentation" tabindex="-1">Maintaining documentation <a class="header-anchor" href="#maintaining-documentation" aria-label="Permalink to &quot;Maintaining documentation&quot;">​</a></h2><p>The README introduces the project and provides a minimal example; <code>docs/</code> explains usage by task and module; <code>examples/README.md</code> provides runnable entry points. Generate complete signatures from source comments instead of maintaining a duplicate set of declarations in handwritten documentation.</p><ul><li>Examples import the public <code>sfml.js</code> package; only repository demo scripts use repository-relative paths.</li><li>Distinguish complete examples from context-dependent snippets, and state requirements for async functions, assets and devices.</li><li>Check loading booleans and network statuses, and close owned resources when examples end.</li><li>When changing public behavior, update JSDoc, the relevant guides and affected examples together.</li></ul><p>Install the website dependencies, then build the website:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:docs</span></span></code></pre></div><p><code>site/</code> contains the VitePress theme and build scripts. The build prepares English, Chinese, Japanese and Korean guides and API references. TypeDoc lives at <code>/reference/</code>, <code>/zh/reference/</code>, <code>/ja/reference/</code> and <code>/ko/reference/</code>; the complete website is written to <code>build/site/</code>. Edit the original Markdown files, then restart <code>npm run docs:dev</code> to refresh prepared content. Theme changes support hot reload.</p><p>Documentation generation does not require compiling or loading the native module; documentation-only environments can first run <code>npm ci --ignore-scripts</code>. <code>npm run build:reference</code> generates standalone TypeDoc in <code>build/docs/</code>, with translations in its <code>zh/</code>, <code>ja/</code> and <code>ko/</code> subdirectories. <code>npm --prefix site test</code> checks localization, link conversion and legacy redirects; the production build also validates generated routes, anchors and assets.</p><p>The <a href="https://github.com/XadillaX/node-sfml/blob/main/.github/workflows/publish-docs.yml" target="_blank" rel="noreferrer">Publish Docs workflow</a> runs on updates to <code>main</code> and also supports manual dispatch. Generated output is committed to <code>docs/</code> on the <code>gh-pages</code> branch, preserving files at that branch&#39;s root and its existing <code>CNAME</code> (<code>sfml.js.org</code>). It skips the commit when generated content is unchanged.</p><p>Legacy TypeDoc class and interface URLs redirect to the corresponding English reference page, preserving fragment links. The API language selector preserves the current page and member anchor.</p><p>Write JSDoc in English first, followed by <code>@zh</code>, <code>@ja</code> and <code>@ko</code> translations. Place each translation immediately after its summary or block tag. Parameter translations use <code>@zh name - description</code> (likewise for Japanese and Korean). Keep identifiers, code examples and links intact. Missing prose translations fail the documentation build.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/**</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * Read the elapsed time.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@zh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 读取经过的时间。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ja</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 経過時間を読み取ります。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ko</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 경과 시간을 읽습니다.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@param</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> unit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> - Time unit.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@zh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 时间单位。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ja</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 時間の単位。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> * </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@ko</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> unit - 시간 단위.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> */</span></span></code></pre></div><p>Generated constant descriptions are maintained in <code>tools/constant-docs.json</code> and the templates in <code>tools/constant-docs.cjs</code>. Run <code>npm run generate:window</code> and <code>npm run generate:network</code> after editing them; do not edit generated comments directly.</p><h2 id="running-examples" tabindex="-1">Running examples <a class="header-anchor" href="#running-examples" aria-label="Permalink to &quot;Running examples&quot;">​</a></h2><p>Run these commands from the repository root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:types</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=120</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:window</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frames=120</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:audio</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:network</span></span></code></pre></div><p>See <a href="/examples">examples/README.md</a> for descriptions. After building, run <code>node examples/&lt;name&gt;.cjs</code> directly. Entry points supporting <code>--frames</code> can limit the frame count; the examples guide also explains how to capture screenshots.</p><p>The two legacy <code>drawAsync</code>/<code>displayAsync</code> examples explicitly report that they are unsupported; see the <a href="/examples/ported">ported examples</a>.</p><h2 id="source-and-generated-files" tabindex="-1">Source and generated files <a class="header-anchor" href="#source-and-generated-files" aria-label="Permalink to &quot;Source and generated files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Contents</th></tr></thead><tbody><tr><td><code>src/</code></td><td>TypeScript implementation</td></tr><tr><td><code>native/</code></td><td>C++ bindings</td></tr><tr><td><code>test/</code></td><td>Runtime, type and native comparison tests</td></tr><tr><td><code>tools/</code></td><td>Constant generators, benchmarks and test tools</td></tr><tr><td><code>docs/</code></td><td>API and development documentation</td></tr><tr><td><code>site/</code></td><td>Website theme, localization, search and build scripts</td></tr></tbody></table><p><code>build/</code>, <code>dist/</code>, <code>node_modules/</code> and downloaded SFML libraries are generated content. Window and network constants are generated from the current SFML headers; do not edit <code>src/*/gen/constants.ts</code> directly.</p><p>Native builds automatically generate <code>build/compile_commands.json</code> for <code>.clangd</code>. To update only the language server configuration, run <code>npm run configure:lsp</code>; restart clangd if the editor still shows stale diagnostics.</p><h2 id="implementation-conventions" tabindex="-1">Implementation conventions <a class="header-anchor" href="#implementation-conventions" aria-label="Permalink to &quot;Implementation conventions&quot;">​</a></h2><p>Value types use TypedArray for calculations and shared storage; native resources and their views keep memory alive. Graphics resources are destroyed on their owning thread. Recorded draws must preserve snapshot semantics: later property changes must not alter previously recorded results.</p><p>Relevant entry points include <code>src/internal/lazy-value.ts</code>, <code>src/internal/graphics-state.ts</code>, <code>native/shared-handle.h</code>, <code>native/deferred-delete.h</code> and <code>native/batch-drawable.h</code>. Add JSDoc describing behavior, parameters and upstream counterparts when adding public fields or methods.</p><p>The downloader, installation hooks and platform builds are interconnected; validate the corresponding platforms when changing them. Download URLs and architecture mappings are in <code>tools/lib_downloader_urls.cjs</code>, and the cache is in <code>third_party/sfml/</code>.</p><h2 id="submitting-changes" tabindex="-1">Submitting changes <a class="header-anchor" href="#submitting-changes" aria-label="Permalink to &quot;Submitting changes&quot;">​</a></h2><p>Describe the specific behavior, relevant verification and unverified platform paths in the PR. Run affected native comparison tests for native changes; check links, code examples and the TypeDoc build for documentation-only changes. Include the machine, Node.js/SFML versions, scenario and measurement method with performance figures.</p>`,48)])])}const k=s(n,[["render",d]]);export{u as __pageData,k as default};
